import threading
import sys
import logging

if sys.version_info[0] >= 3:
    from queue import Queue, Empty
else:
    from Queue import Queue, Empty


class MessageDispatcher(object):
    '''
    Entity responsible for resending messages from the input queues to subscribed observers.

    Decision whether observer should receive message is based on message_type and message_owner defined by the observer.
    Not-awaited messages are thrown away
    '''
    def __init__(self, queues_list):
        self._queues_list = queues_list
        self._subscribed_observers = []
        self.is_running = threading.Event()
        self.dequeue_timeout = 0.01
        self.single_run_dequeue_limit = 100
        self._dispatcher_ended = threading.Semaphore(0)
        self._dispatcher_started = threading.Semaphore(0)
        self.logger = logging.getLogger('messaging.dispatcher')
        self.logger.debug("%s created" % self)
        thread_name = "Dispatcher-Thread"
        dispatcher_thread = threading.Thread(target=self.start, name=thread_name)
        dispatcher_thread.daemon = True
        dispatcher_thread.start()
        self._dispatcher_started.acquire()

    def __str__(self):
        dispatching_input = 'msg_src#:%d' % len(self._queues_list)
        dispatching_output = 'subscr#:%d' % len(self._subscribed_observers)
        name = self.__class__.__name__
        return '%s(%s --> %s)' % (name, dispatching_input, dispatching_output)

    # @TracedIn('messaging.dispatcher')  # falsifies documentation of parameters
    def add_source(self, queue):
        '''
        :param queue: Queue object instance bshared between MessageDispatcher and MessageSource
        :return: None
        '''
        self.logger.trace("%s add_source(%s)" % (self, queue))
        self._queues_list.append(queue)

    def remove_source(self, queue_to_remove):
        '''
        :param queue_to_remove: Queue object correspoding to source that is to to be removed
        :return: None
        '''
        self.logger.trace("%s remove_source(%s)" % (self, queue_to_remove))
        self._queues_list = [queue_left for queue_left in self._queues_list if
                             queue_left is not queue_to_remove]

    def subscribe_observer(self, msg_queue, message_type, owner, is_running=None):
        '''
        Allows observers to subscribe their interests in specific message type

        :param msg_queue: observers queue to which matching messages should be sent
        :param message_type: observers desired message type
        :param owner: observers desired message owner
        :param is_running: event holding information if observer is not in state of not accepting messages
        '''
        if (owner is None) or (message_type is None):
            self._is_matching = self._is_matching_slower_version

        # self.logger.trace("%s subscribe_observer(%s, %s, %s)" % (self, msg_queue, message_type, owner))
        observer_data = ObserverSelectedData(msg_queue, message_type, owner, is_running)
        self._subscribed_observers.append(observer_data)

    def unsubscribe_observer(self, observer_queue):
        '''
        Allows observers to unsubscribe at their will

        :param observer_queue: observer queue of instance of MessageObserver that should be unsubscribed
        '''
        self.logger.trace("%s unsubscribe_observer(%s)" % (self, observer_queue))
        self._subscribed_observers = [sub_obs for sub_obs in self._subscribed_observers if
                                      observer_queue is not sub_obs.msg_queue]

    def stop(self):
        '''
        Terminates dispatcher loop and cleans up
        '''
        if self.is_running.is_set():
            self.is_running.clear()
            self._dispatcher_ended.acquire()
        self.logger.info("%s stopped" % self)

    @staticmethod
    def _is_matching_by_owner_and_msg_type(observer_data, message):
        try:
            if observer_data.owner == message.owner and observer_data.message_type == message.message_type:
                return True
            else:
                return False
        except Exception as err:
            MessageDispatcher._report_matching_error(observer_data, message, err)
            return False

    @staticmethod
    def _is_matching_slower_version(observer_data, message):
        try:
            if observer_data.owner is None and observer_data.message_type is None:  # means: give me all messages
                return True
            elif observer_data.message_type is None:      # only message type is None
                if observer_data.owner == message.owner:  # give me all of that owner
                    return True
                else:
                    return False
            elif observer_data.owner is None:       # only owner is None
                if observer_data.message_type == message.message_type:  # give me all of that message_type
                    return True
                else:
                    return False
            elif observer_data.owner == message.owner and observer_data.message_type == message.message_type:
                return True
            else:
                return False
        except Exception as err:
            MessageDispatcher._report_matching_error(observer_data, message, err)
            return False

    _is_matching = _is_matching_by_owner_and_msg_type  # this is default

    def start(self):
        '''
        Starts dispatcher loop.
        '''
        self.is_running.set()
        self._dispatcher_started.release()
        self.logger.info("%s started" % self)
        self.logger.debug('{!s} thread started'.format(self))
        while self.is_running.is_set():
            for queue in self._queues_list:
                try:
                    for i in list(range(1, self.single_run_dequeue_limit)):
                        unparsed_message = queue.get(timeout=self.dequeue_timeout)
                        self.logger.debug('%s <<< %s, left in msg_src: %d' % (self, unparsed_message, queue.qsize()))
                        self._send_message_to_proper_subscribers(unparsed_message)
                except Empty:
                    continue

        self.logger.debug('%s  loop finished' % self)
        self._dispatcher_ended.release()
        self.logger.debug('{!s} thread finished'.format(self))

    def _send_message_to_proper_subscribers(self, unparsed_message):
        message_was_sent = False
        for observer_data in self._subscribed_observers:
            msg_looks_awaited_by_observer = self._is_matching(observer_data, unparsed_message)
            if msg_looks_awaited_by_observer:
                observer_data.msg_queue.put(unparsed_message)
                self.logger.debug('%s >>> %s' % (self, observer_data))
                message_was_sent = True
        if not message_was_sent:
            self._drop_message(unparsed_message)

    def _drop_message(self, unparsed_message):
        self.logger.debug('%s [x] %s' % (self, unparsed_message))

    @staticmethod
    def _report_matching_error(observer_data, message, error):
        logger = logging.getLogger('messaging.dispatcher')
        err_msg = 'matching {} <-vs-> {} FAILED: {!r}'.format(observer_data, message, error)
        logger.warning(err_msg)


class ObserverSelectedData(object):
    def __init__(self, msg_queue, message_type, owner, is_running):
        self.msg_queue = msg_queue
        self.message_type = message_type
        self.owner = owner
        self.is_running = is_running

    def __str__(self):
        return 'ObserverAwaiting(%s, owner:%s, at:%s, is_running:%s)' % (self.message_type, self.owner, self.msg_queue, self.is_running)

    def __eq__(self, other):
        return ((self.msg_queue == other.msg_queue)
                and (self.message_type == other.message_type)
                and (self.owner == other.owner))
